create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, phone_number text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.saved_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, menu_item_id text not null, created_at timestamptz not null default now(), unique(user_id,menu_item_id));
create table public.carts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'active' check(status in('active','converted','abandoned')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,status));
create table public.cart_items (id uuid primary key default gen_random_uuid(), cart_id uuid not null references public.carts(id) on delete cascade, menu_item_id text not null, quantity integer not null check(quantity>0), selected_options jsonb, special_instructions text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(cart_id,menu_item_id));
alter table public.profiles enable row level security;alter table public.saved_items enable row level security;alter table public.carts enable row level security;alter table public.cart_items enable row level security;
create policy "profile owner" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "saved owner" on public.saved_items for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "cart owner" on public.carts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "cart items owner" on public.cart_items for all using(exists(select 1 from public.carts where id=cart_id and user_id=auth.uid())) with check(exists(select 1 from public.carts where id=cart_id and user_id=auth.uid()));
create index saved_items_user_idx on public.saved_items(user_id);create index cart_items_cart_idx on public.cart_items(cart_id);
